#[test]
fn parse_every_abbreviation() {
    assert_eq!(
        "A".parse::<ElectricCurrentUnit>(),
        Ok(ElectricCurrentUnit::Ampere)
    );
    assert_eq!(
        format!("2.5 {}", "A").parse::<ElectricCurrent>(),
        Ok(ElectricCurrent::new(2.5, ElectricCurrentUnit::Ampere))
    );
    assert_eq!(
        "fA".parse::<ElectricCurrentUnit>(),
        Ok(ElectricCurrentUnit::Femtoampere)
    );
    assert_eq!(
        format!("2.5 {}", "fA").parse::<ElectricCurrent>(),
        Ok(ElectricCurrent::new(2.5, ElectricCurrentUnit::Femtoampere))
    );
    assert_eq!(
        "pA".parse::<ElectricCurrentUnit>(),
        Ok(ElectricCurrentUnit::Picoampere)
    );
    assert_eq!(
        format!("2.5 {}", "pA").parse::<ElectricCurrent>(),
        Ok(ElectricCurrent::new(2.5, ElectricCurrentUnit::Picoampere))
    );
    assert_eq!(
        "nA".parse::<ElectricCurrentUnit>(),
        Ok(ElectricCurrentUnit::Nanoampere)
    );
    assert_eq!(
        format!("2.5 {}", "nA").parse::<ElectricCurrent>(),
        Ok(ElectricCurrent::new(2.5, ElectricCurrentUnit::Nanoampere))
    );
    assert_eq!(
        "µA".parse::<ElectricCurrentUnit>(),
        Ok(ElectricCurrentUnit::Microampere)
    );
    assert_eq!(
        format!("2.5 {}", "µA").parse::<ElectricCurrent>(),
        Ok(ElectricCurrent::new(2.5, ElectricCurrentUnit::Microampere))
    );
    assert_eq!(
        "mA".parse::<ElectricCurrentUnit>(),
        Ok(ElectricCurrentUnit::Milliampere)
    );
    assert_eq!(
        format!("2.5 {}", "mA").parse::<ElectricCurrent>(),
        Ok(ElectricCurrent::new(2.5, ElectricCurrentUnit::Milliampere))
    );
    assert_eq!(
        "cA".parse::<ElectricCurrentUnit>(),
        Ok(ElectricCurrentUnit::Centiampere)
    );
    assert_eq!(
        format!("2.5 {}", "cA").parse::<ElectricCurrent>(),
        Ok(ElectricCurrent::new(2.5, ElectricCurrentUnit::Centiampere))
    );
    assert_eq!(
        "kA".parse::<ElectricCurrentUnit>(),
        Ok(ElectricCurrentUnit::Kiloampere)
    );
    assert_eq!(
        format!("2.5 {}", "kA").parse::<ElectricCurrent>(),
        Ok(ElectricCurrent::new(2.5, ElectricCurrentUnit::Kiloampere))
    );
    assert_eq!(
        "MA".parse::<ElectricCurrentUnit>(),
        Ok(ElectricCurrentUnit::Megaampere)
    );
    assert_eq!(
        format!("2.5 {}", "MA").parse::<ElectricCurrent>(),
        Ok(ElectricCurrent::new(2.5, ElectricCurrentUnit::Megaampere))
    );
    assert_eq!(
        "1 not-a-unit".parse::<ElectricCurrent>(),
        Err(ParseError::UnknownUnit)
    );
}

#[test]
fn arithmetic_f64() {
    let a = ElectricCurrent::from_base(6.0);
    let b = ElectricCurrent::from_base(2.0);
    assert_eq!((a + b).as_base(), 8.0);
    assert_eq!((a - b).as_base(), 4.0);
    assert_eq!((-a).as_base(), -6.0);
    assert_eq!((a * 2.0).as_base(), 12.0);
    assert_eq!((2.0 * a).as_base(), 12.0);
    assert_eq!((a / 2.0).as_base(), 3.0);
    assert_eq!(a / b, 3.0);
    let mut c = a;
    c += b;
    c -= b;
    c *= 2.0;
    c /= 4.0;
    assert_eq!(c.as_base(), 3.0);
}

#[test]
fn arithmetic_integer() {
    let a = ElectricCurrent::<i64>::from_base(7);
    let b = ElectricCurrent::<i64>::from_base(2);
    assert_eq!(a + b, ElectricCurrent::from_base(9));
    assert_eq!(a % b, ElectricCurrent::from_base(1));
    assert_eq!(a / b, 3);
    assert!(a > b);
    assert_eq!(
        [a, b].iter().sum::<ElectricCurrent<i64>>(),
        ElectricCurrent::from_base(9)
    );
}
